	// Try to open the loop device with O_NONBLOCK to avoid blocking if already in use.
	// We'll retry without O_NONBLOCK if EBUSY is encountered.
	fd, err := unix.Open(loopDev, unix.O_RDWR|unix.O_NONBLOCK, 0)
	if err != nil {
