// Listen starts listening on the server's configured address.
func (s *Server) Listen() error {
	ln, err := net.Listen("tcp", s.Addr)
	if err != nil {
		return err
	}
	s.listeners = append(s.listeners, ln)
	return nil
}

// Serve starts the server, accepting incoming connections.
func (s *Server) Serve() error {
	if len(s.listeners) == 0 {
		return fmt.Errorf("no listeners; call Listen() first")
	}
	for _, ln := range s.listeners {
		go s.serveListener(ln)
	}
