	return nil
}

func (ph *PublishHandler) publish(addr string, body []byte) error {
	startTime := time.Now()
	var err error
	if strings.HasPrefix(addr, "http") {
		if strings.Contains(addr, "%s") {
			addr = fmt.Sprintf(addr, url.QueryEscape(string(body)))
		}
		err = ph.doRequest(addr, body)

