func (c *BootstrapConfig) GenerateJSON(args *BootstrapTplArgs) ([]byte, error) {
	if err := c.ConfigureArgs(args); err != nil {
		return nil, err
	}
	t, err := template.New("bootstrap").Parse(c.Template())
	if err != nil {
		return nil, err
	}
	var buf bytes.Buffer
	err = t.Execute(&buf, args)
	if err != nil {
		return nil, err
	}

