// GenerateConfig takes a BootstrapConfig and returns a rendered JSON config for
// an Envoy bootstrap. It is assumed to be called after the config has been
// validated.
func (c *BootstrapConfig) GenerateConfig(args *BootstrapConfigArgs) ([]byte, error) {
	tmpl := template.New("bootstrap").Funcs(template.FuncMap{
		"localizeAddr": localizeAddr,
		"isIP":         isIP,
		"toJSON":       toJSON,
	})

	tmpl, err := tmpl.Parse(c.Template())
	if err != nil {
		return nil, fmt.Errorf("failed to parse template: %v", err)
	}

	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, args); err != nil {
		return nil, fmt.Errorf("failed to execute template: %v", err)
	}

	// Parse the rendered template to a map so we can modify it.
	var config map[string]interface{}
	if err := json.Unmarshal(buf.Bytes(), &config); err != nil {
		return nil, fmt.Errorf("failed to unmarshal template output: %v", err)

