// GenerateConfig generates a new bootstrap config.
func (c *BootstrapConfig) GenerateConfig(args *BootstrapConfigArgs) ([]byte, error) {
	tmpl, err := template.New("bootstrap").Parse(c.Template())
	if err != nil {
		return nil, fmt.Errorf("failed to parse template: %v", err)
	}

	var buf bytes.Buffer
	if err := tmpl.Execute(&buf, args); err != nil {
		return nil, fmt.Errorf("failed to execute template: %v", err)
	}

	// Parse the generated JSON so we can modify it.
	var m map[string]interface{}
	if err := json.Unmarshal(buf.Bytes(), &m); err != nil {
		return nil, fmt.Errorf("failed to unmarshal bootstrap json: %v", err)
	}

	// Apply any custom configuration.
	if err := c.applyStatsSinks(m); err != nil {
		return nil, err
	}
	if err := c.applyStatsConfig(m); err != nil {
		return nil, err
	}
	if err := c.applyStatsFlushInterval(m); err != nil {
		return nil, err
	}
	if err

