		return qps, achievedSLI, err
	}

	qps, achievedSLI, err = m.getQPSAndLatencyFrom(stdoutFile)
	if err != nil {
		return qps, achievedSLI, err
	}

	if m.config.EraseTuneOutput {
		if err = taskHandle.EraseOutput(); err != nil {
			logrus.Error("mutilate.Tune(): EraseOutput on master failed: ", err)
			return 0, 0, err
		}
	}

	return qps, achievedSLI, err
}

// Load starts a load on the specific workload with the defined loadPoint (number of QPS).
// The task will do the load for specified amount of time.
func (m mutilate) Load(qps int, duration time.Duration) (executor.TaskHandle, error) {
	agentHandles, err := m.runRemoteAgents()
	if err != nil {
		return nil, err
	}

	loadCommand := getLoadCommand(m.config, qps, duration, agentHandles)
	masterHandle, err := m.master.Execute(loadCommand)
	if err != nil {
		stopAgents(agentHandles)
		return nil, errors.Wrapf(err,
			"execution of Mutilate Master Load failed. command: %q",
			loadCommand)
	}

	return executor.NewClusterTaskHandle(masterHandle, agentHandles), nil
}

// Approach based on http://stackoverflow.com/a/11398748.
func bits(v uint64) byte {
	if v == 0 {
		return 0
	}
	v <<= 2
	v--
	v |= v >> 1
	v |= v >> 2
	v |= v >> 4
	v |= v >> 8
	v |= v >> 16
	v |= v >> 32
	return tab64[((v-(v>>1))*0x07EDD5E59A4E28C2)>>58] - 1
}

// pool contains size stratified workspace Dense pools.
// Each pool element i returns sized matrices with a data
// slice capped at 1<<i.
var pool [63]sync.Pool

func init() {
	for i := range pool {
		l := 1 << uint(i)
		pool[i].New = func() interface{} {
			return &Dense{mat: blas64.General{
				Data: make([]float64, l),
			}}
		}
	}
}

// getWorkspace returns a *Dense of size r×c and a data slice
// with a cap that is less than 2*r*c. If clear is true, the
// data slice visible through the Matrix interface is zeroed.
func getWorkspace(r, c int, clear bool) *Dense {
	l := uint64(r * c)
	w := pool[bits(l)].Get().(*Dense)
	w.mat.Data = w.mat.Data[:l]
	if clear {
		zero(w.mat.Data)
	}
	w.mat.Rows = r
	w.mat.Cols = c
	w.mat.Stride = c
	w.capRows = r
	w.capCols = c
	return w
}

// putWorkspace replaces a used *Dense into the appropriate size
// workspace pool. putWorkspace must not be called with a matrix
// where references to the underlying data slice has been kept.
func putWorkspace(w *Dense) {
	pool[bits(uint64(cap(w.mat.Data)))].Put(w)
}

