func (l *Librato) Connect() error {
	if l.ApiUser == "" || l.ApiToken == "" {
		return fmt.Errorf("api_user and api_token are required")
	}

	if l.client == nil {
		l.client = &http.Client{
			Timeout: l.Timeout.Duration,
		}
	}

	if l.apiUrl == "" {
		l.apiUrl = librato_api
	}

	return nil
}

